def create_files_with_content():
    # Bayanan sirrin
    content = {
        "file1.txt": "Na gaskiya da ƙarfe 1",
        "file2.txt": "Na gaskiya da ƙarfe 2",
        "file3.txt": "Na gaskiya da ƙarfe 3"
    }

    # Rubuta fayil ɗin bayanan sirrin zuwa gare ta
    for filename, text in content.items():
        with open(filename, 'w') as f:
            f.write(text)
        print(f"Fayil {filename} zai zama da kamar {text}")

# 2. Canza izini na fayil ɗin don karantawa kawai don mai shi
def rename_files():
    import os
    # Daga cikin fayil ɗin kuma bayani ƙarfe
    for filename in os.listdir():
        if filename.startswith("file") and filename.endswith(".txt"):
            # Canza izini na fayil ɗin don karantawa kawai don mai shi
            new_name = "new_" + filename
            os.rename(filename, new_name)
            print(f"Za canza izini na {filename} zuwa {new_name}")

# 3. Buga sunan fayil ɗin zuwa allon
def list_files():
    import os
    print("\nFayil ɗin zai zama:")
    for file in os.listdir():
        if file.endswith(".txt"):
            print(file)

